import{_ as i,o as s,c as l,a3 as t,j as e,a as r}from"./chunks/framework.z_KJ15Ep.js";const u="/bilder/grundschule/tutorials-gs-hybrid-kataloge.png",d="/bilder/grundschule/tutorials-gs-hybrid-fachbez-lb.png",m=JSON.parse('{"title":"Hybridzeugnisse für die Grundschule erstellen","description":"","frontmatter":{"title":"Hybridzeugnisse für die Grundschule erstellen","source_pageid":1404,"source_revision":6865},"headers":[],"relativePath":"zeugnisse/grundschule/grundschulzeugnisse-hybridzeugnis-tutorial.md","filePath":"zeugnisse/grundschule/grundschulzeugnisse-hybridzeugnis-tutorial.md"}'),a={name:"zeugnisse/grundschule/grundschulzeugnisse-hybridzeugnis-tutorial.md"};function o(g,n,h,c,p,z){return s(),l("div",null,[...n[0]||(n[0]=[t('<h1 id="hybridzeugnisse-fur-die-grundschule-erstellen" tabindex="-1">Hybridzeugnisse für die Grundschule erstellen <a class="header-anchor" href="#hybridzeugnisse-fur-die-grundschule-erstellen" aria-label="Permalink to &quot;Hybridzeugnisse für die Grundschule erstellen&quot;">​</a></h1><p>Verbinden Sie Ankreuzkompetenzen mit Floskeln und freien Texten. Bereiten Sie beide Bestandteile vor und verwenden Sie die zugehörigen Hybridzeugnisvorlagen.</p><p>Nehmen Sie die Tutorials zu den Ankreuzzeugnissen und den Floskelzeugnissen zur Kenntnis. Dort wird das Konfigurieren von Ankreuzkompetenzen und Floskeln ausführlich beschrieben.</p><p>Dieser Artikel dient daher als verkürzte Übersicht für Hybridzeugnisse in SchILD-NRW 3.</p><p>Die Vorlagen für das Hybridzeugnis finden sich im Bereich der Grundschulzeugnisse auf der Webseite des MSB für Schulverwaltungssoftware.</p><p><a href="/bilder/grundschule/tutorials-gs-hybrid-kataloge.png"><img src="'+u+'" alt="Die Kataloge, über die sich Ankreuzkompetenzen und Floskeln steuern lassen." loading="lazy"></a></p><p><em>Die Kataloge, über die sich Ankreuzkompetenzen und Floskeln steuern lassen.</em></p><h2 id="kompetenzen-und-floskeln-verbinden" tabindex="-1">Kompetenzen und Floskeln verbinden <a class="header-anchor" href="#kompetenzen-und-floskeln-verbinden" aria-label="Permalink to &quot;Kompetenzen und Floskeln verbinden&quot;">​</a></h2><p>Hybridzeugnisse lassen sich wie die beiden anderen Typen der Grundschulzeugnisse erzeugen. Je nach schulischer Festlegung werden <strong>Ankreuzkompetenzen</strong> zu den Fächern sowie zum <em>Arbeits- und Sozialverhalten</em> über <em>Kataloge ➜ Ankreuzkompetenzen definieren</em> eingerichtet.</p><p>Die für die Fächer definierten Ankreuzkompetenzen werden anschließend über <em>Gruppenprozesse ➜ Noten/Zeugnisvorbereitung ➜ Ankreuzkompetenzen eintragen</em> den Schülerinnen und Schülern einer zuvor ausgewählten Schülergruppe (zum Beispiel eines Jahrgangs) zugeordnet.</p><p>Zusätzlich werden <strong>Floskeln zu den Fächern</strong> über <em>Kataloge ➜ Floskeln</em> für die gewünschten Jahrgänge definiert.</p><p><a href="/bilder/grundschule/tutorials-gs-hybrid-fachbez-lb.png"><img src="'+d+'" alt="Mit einem Rechtsklick öffnet sich der Floskeleditor." loading="lazy"></a></p><p><em>Mit einem Rechtsklick öffnet sich der Floskeleditor.</em></p><p>Die Floskeln werden anschließend über <em>Schüler ➜ Leistungsdaten</em> im <em>aktuellen Lernabschnitt</em> im Bereich <strong>Fachbezogene Leistungsentwicklung</strong> eingetragen.</p><p>Ein <code>Rechtsklick</code> auf <strong>Fachbez. Leistungsentw.</strong> öffnet den Floskeleditor.</p><p>Je nach Entscheidung der Schule sind in diesem Feld auch zusätzliche oder ausschließlich manuelle Texteingaben ohne Floskeln möglich.</p><p>Über die Webseite des MSB für Schulverwaltungssoftware kann im Bereich <em>Downloads ➜ Zeugnisse</em> unter <strong>Grundschulzeugnisse in Hybridform</strong> das Paket mit den Hybridzeugnisreports heruntergeladen werden.</p><p>Das Zeugnis wird über die Datei <em>HybridzeugnisEinstellungen.ini</em> konfiguriert. Diese Konfigurationsdatei funktioniert wie in den anderen Tutorials zum Zeugnisdruck beschrieben.</p><p>Darüber lässt sich die Fächerreihenfolge festlegen, ebenso ab welchem Jahrgang <strong>Noten</strong> ausgegeben werden und ob der Notenblock zweispaltig dargestellt werden soll.</p>',19),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),r("Hinweis – Siehe auch")]),e("ul",null,[e("li",null,[e("a",{href:"/reporting/zeugnisformulare/zeugnisse-themenuebersicht.html"},"Den Zeugnisdruck vorbereiten")]),e("li",null,[e("a",{href:"/reporting/zeugnisformulare/zeugnisformulare-herunterladen-und-aktualisieren.html"},"Zeugnisformulare herunterladen und bereitstellen")])])],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Grundschulzeugnisse_Hybridzeugnis_(Tutorial)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),r(" · Quellrevision 6865.")],-1)])])}const k=i(a,[["render",o]]);export{m as __pageData,k as default};
